custom_css:
@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-webfont@1.7.0/style.css");

/* ============================================================
   薄荷手帐 · 简约  Mint Bujo
   薄荷绿 x 奶油白 ｜ 清爽手帐 ｜ 纯 CSS 不依赖外部图床
   ============================================================ */

:root {
  /* ── 文本 ── */
  --text-main:        #4E6A5E;
  --text-italic:      #C8968C;
  --text-underline:   #C5A796;
  --text-quote:       #78A08C;
  --text-soft:        #8FA895;

  /* ── 背景 / 卡片 ── */
  --bg-chat:          #FFFCF4;   /* 卡片奶油白 */
  --bg-ui:            #F3F9F3;   /* UI 背景（带绿意）*/
  --bg-ai:            #F5FBF6;   /* AI 卡片 · 淡薄荷奶白 */
  --bg-user:          #FDF6EE;   /* 用户卡片 · 淡奶油 */

  /* ── 边框 / 网格 ── */
  --border-ui:        #C9E2D2;   /* 边框 · 淡薄荷 */
  --grid-line:        #E7F0E8;   /* AI 横线纸 · 极淡绿 */
  --grid-line-user:   #F3E8DC;   /* 用户横线纸 · 淡奶油 */

  /* ── 点缀色 ── */
  --accent-mint-1:    #9FD3B4;   /* 主薄荷绿 */
  --accent-mint-2:    #D6EBDF;   /* 浅薄荷 */
  --accent-peach:     #F5C6B8;   /* 蜜桃 */
  --accent-cream:     #F7E2C9;   /* 奶油黄 */
  --accent-ink:       #7B996F;   /* 深一点绿 · 按钮文字 */
  --card-shadow:      rgba(120,150,130,0.16);
}

/* ── 字体（霞鹜文楷，排除图标字）── */
body *:not(.fa):not(.fas):not(.fab):not(.far):not(.fa-solid):not(.fa-regular):not(.fa-brands):not([class*="fa-"]) {
  font-family: "霞鹜文楷", "LXGW WenKai", "Kaiti SC", "STKaiti", "PingFang SC", "Microsoft YaHei", serif !important;
  font-weight: normal !important;
}

/* ── 全局：去文字阴影、轻滚动条 ── */
* {
  text-shadow: none !important;
  scrollbar-width: thin;
  scrollbar-color: var(--border-ui) transparent;
}
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--accent-mint-1); border-radius: 8px; }

/* ============================================================
   背景：自带柔和奶油→淡薄荷渐变，不依赖外部壁纸
   ============================================================ */
#sheld { background: transparent !important; }
#chat {
  background: linear-gradient(180deg, #FFFDF6 0%, #F6FBF4 60%, #F1F8F2 100%) !important;
  border: none !important;
  padding: 22px 0 96px !important;
}

/* 首页 / 列表面板保持奶白 */
.welcomePanel, #rm_print_characters_block, #rm_group_chats_block {
  background-color: rgba(255,252,244,0.94) !important;
}

/* ── 暗色：覆盖上面的「首页保持奶白」（同优先级，后加载者赢） ── */
body.hana-dark .welcomePanel,
body.hana-dark #rm_print_characters_block,
body.hana-dark #rm_group_chats_block,
body.hana-dark .welcomePanel .interactable {
  background-color: rgba(37, 51, 45, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}
body.hana-dark .welcomePanel h3,
body.hana-dark .welcomePanel p,
body.hana-dark .welcomePanel label,
body.hana-dark .welcomePanel input,
body.hana-dark .welcomePanel select,
body.hana-dark .welcomePanel textarea {
  color: rgba(216, 230, 221, 1) !important;
}
body.hana-dark .welcomePanel input,
body.hana-dark .welcomePanel select,
body.hana-dark .welcomePanel textarea {
  background: rgba(30, 41, 36, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}


/* ============================================================
   消息卡片：手帐纸感（圆角 + 淡描边 + 横线纸 + 顶部胶带）
   ============================================================ */
body.bubblechat #chat .mes {
  margin: 18px 0 !important;
  padding: 0 4px !important;
  background: transparent !important;
  border: none !important;
  overflow: visible !important;
}

/* 卡片本体 */
#chat .mes .mes_block {
  position: relative !important;
  width: calc(100% - 40px) !important;
  margin: 0 auto !important;
  box-sizing: border-box;
  background-color: var(--bg-ai);
  background-image: repeating-linear-gradient(0deg, var(--grid-line) 0 1px, transparent 1px 27px);
  background-position: left top;
  border: 1px solid var(--border-ui) !important;
  border-radius: 16px !important;
  padding: 22px 26px 20px 26px !important;
  box-shadow: 0 4px 16px var(--card-shadow) !important;
}

/* 顶部「胶带」贴纸：半透明斜纹，压在卡片顶部中线 */
#chat .mes .mes_block::before {
  content: "";
  position: absolute;
  top: -11px;
  left: 50%;
  transform: translateX(-50%) rotate(-2deg);
  width: 96px;
  height: 22px;
  background:
    repeating-linear-gradient(45deg,
      rgba(159,211,180,0.55) 0 6px,
      rgba(255,255,255,0.45) 6px 12px);
  border-left: 1px solid rgba(255,255,255,0.5);
  border-right: 1px solid rgba(255,255,255,0.5);
  border-radius: 2px;
  box-shadow: 0 2px 5px rgba(120,150,130,0.18);
  pointer-events: none;
  z-index: 3;
}

/* 用户卡片：淡奶油 + 更暖的横线纸 + 蜜桃胶带 */
#chat .mes[is_user="true"] .mes_block {
  background-color: var(--bg-user);
  background-image: repeating-linear-gradient(0deg, var(--grid-line-user) 0 1px, transparent 1px 27px);
}
#chat .mes[is_user="true"] .mes_block::before {
  background:
    repeating-linear-gradient(45deg,
      rgba(245,198,184,0.60) 0 6px,
      rgba(255,255,255,0.45) 6px 12px);
}

/* 小系统消息：无胶带、无横线纸，更素 */
#chat .mes.smallSysMes .mes_block {
  background-image: none !important;
  padding: 10px 18px !important;
}
#chat .mes.smallSysMes .mes_block::before { display: none !important; }

/* ============================================================
   头像：圆角贴纸（白色描边 + 轻阴影）
   ============================================================ */
#chat .mes .mesAvatarWrapper {
  position: relative !important;
  margin: 0 auto 10px !important;
  width: 56px !important;
  height: 56px !important;
  transform: none !important;
  overflow: visible !important;
  z-index: 2;
}
#chat .mes .avatar {
  width: 56px !important;
  height: 56px !important;
  min-width: 56px !important;
  border-radius: 14px !important;
  overflow: hidden !important;
  flex-shrink: 0;
  background: #FFF !important;
  box-shadow: 0 0 0 2px #fff, 0 3px 10px var(--card-shadow) !important;
}
#chat .mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  border-radius: 14px !important;
}
#chat .mes .avatar::before,
#chat .mes .avatar::after { content: none !important; display: none !important; }

/* ============================================================
   顶栏
   ============================================================ */
#top-bar, .top-bar, #topControls {
  background: rgba(255,252,244,0.92) !important;
  border-bottom: 1px solid var(--border-ui) !important;
}
#top-bar, .top-bar {
  backdrop-filter: blur(10px) !important;
}

/* ============================================================
   底栏输入区
   ============================================================ */
#form_sheld { background: transparent !important; padding: 0 8px; }
#send_form {
  background-color: rgba(255,252,244,0.85) !important;
  border-radius: 18px !important;
  border: 1px solid var(--border-ui) !important;
  outline: none !important;
  box-shadow: 0 4px 18px var(--card-shadow) !important;
  backdrop-filter: blur(10px) !important;
}
#send_textarea {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--text-main) !important;
  caret-color: var(--accent-mint-1);
  resize: none !important;
}

/* 底栏图标统一薄荷绿 */
#send_form :is(.fa, .fas, .far, .fa-solid, .fa-regular, [class*="fa-"]) {
  color: var(--text-soft) !important;
  font-size: 15px !important;
  opacity: 1 !important;
}

/* 发送/生成：薄荷绿圆钮 */
#send_but, #mes_stop {
  background-color: var(--accent-mint-1) !important;
  color: #fff !important;
  border-radius: 50% !important;
}
#send_but:hover, #mes_stop:hover { background-color: var(--accent-ink) !important; }

/* ============================================================
   公共控件：按钮 / 输入 / 滑块 / checkbox 统一薄荷
   ============================================================ */
.menu_button {
  background-color: var(--accent-mint-2) !important;
  color: var(--text-main) !important;
  border: 1px solid var(--border-ui) !important;
  border-radius: 10px !important;
  box-shadow: none !important;
}
.menu_button:hover { background-color: var(--accent-mint-1) !important; color: #fff !important; }

select, .text_pole,
textarea:not(#send_textarea),
input[type="text"], input[type="number"], input[type="search"] {
  background-color: var(--bg-ui) !important;
  border: 1px solid var(--border-ui) !important;
  color: var(--text-main) !important;
  border-radius: 8px !important;
}
select option { background-color: var(--bg-chat) !important; color: var(--text-main) !important; }

input[type="checkbox"] {
  accent-color: var(--accent-ink) !important;
}

/* 滑块：薄荷绿条 + 白色圆点 */
input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  height: 6px !important;
  border-radius: 4px !important;
  background: var(--accent-mint-2) !important;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  appearance: none !important;
  width: 18px !important;
  height: 18px !important;
  border-radius: 50% !important;
  background: var(--accent-mint-1) !important;
  border: 2px solid #fff !important;
  box-shadow: 0 1px 4px var(--card-shadow) !important;
}
input[type="range"]::-moz-range-thumb {
  width: 18px !important;
  height: 18px !important;
  border-radius: 50% !important;
  background: var(--accent-mint-1) !important;
  border: 2px solid #fff !important;
}

/* Tag */
.tag {
  background: rgba(159,211,180,0.18) !important;
  border-color: rgba(159,211,180,0.45) !important;
  color: var(--text-quote) !important;
}

/* ============================================================
   弹窗 / 菜单 / 面板
   ============================================================ */
.popup, .dialog-popup,
.ui-widget.ui-widget-content, #dialogue_popup, #options, #extensionsMenu,
#bulk_tag_popup, #select_chat_popup, #floatingPrompt, #cfgConfig {
  background-color: var(--bg-chat) !important;
  border: 1px solid var(--border-ui) !important;
  color: var(--text-main) !important;
  border-radius: 12px !important;
}

/* 折叠面板标题：奶油黄渐变 */
.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background: linear-gradient(to right, var(--accent-cream) 50%, transparent 100%) !important;
  border: none !important;
  border-left: 3px solid var(--accent-peach) !important;
  border-radius: 6px !important;
  color: var(--text-main) !important;
}
.text_muted { color: var(--text-soft) !important; }

/* 预设管理器 */
#completion_prompt_manager,
#completion_prompt_manager :is(span, a, li, small, code, .completion_prompt_manager_prompt) {
  color: var(--text-main) !important;
}

/* 世界书 */
.world_entry, .worldInfoEntry, .world_info_entry {
  background-color: var(--bg-ui) !important;
  border: 1px solid var(--border-ui) !important;
  border-radius: 8px !important;
  color: var(--text-main) !important;
}

/* 首页 */
.welcomePanel {
  background: rgba(255,252,244,0.92);
  border: 1px solid var(--border-ui);
  border-radius: 12px;
}
.recentChatList .recent-chat-item {
  background: rgba(255,252,244,0.8);
  border: 1px solid var(--border-ui);
  border-radius: 8px;
}
.recentChatList .recent-chat-item:hover { background: rgba(214,235,223,0.6); }

/* ============================================================
   移动端适配
   ============================================================ */
@media (max-width: 1000px) {
  #left-nav-panel, #right-nav-panel, .drawer-content { margin-top: 0; }
}
@media (max-width: 768px) {
  #chat .mes .mes_block { padding: 18px 16px 16px !important; width: calc(100% - 20px) !important; }
  body.bubblechat #chat .mes { padding: 0 2px !important; }
}


/* ═══════════════════════════════════════════════════════════════


