/* hover 反馈：微提亮 + 淡薄荷圆底，像手帐印章 */
#top-settings-holder .drawer-icon:hover,
#top-bar .drawer-icon:hover,
.drawer .drawer-icon:hover {
  filter: brightness(1.15);
  background-color: rgba(159, 211, 180, 0.18) !important;
  border-radius: 8px;
}

/* ═══════════════════════════════════════════════════════════════
   暗色覆盖层 · 跟随 Hana 主题（html.hana-dark / body.hana-dark）
   Hana 切到暗色主题（midnight/midnight-contrast）时，
   花酿内嵌酒馆若仍使用「薄荷手帐 · 简约」则自动套用本层。
   深绿黑底 · 保留手帐质感 · 薄荷绿 accent。
   颜色全部用 ST 原生 rgba(r,g,b,a) 格式（参考官方 Dark Lite 主题），
   不用 hex —— ST 的 SmartTheme 变量会被 rgba(var(--x), 0.8) 这类用法消费，
   hex 会导致 rgba(#xxx, 0.8) 无效，背景覆盖不上。
   ═══════════════════════════════════════════════════════════════ */
html.hana-dark,
body.hana-dark,
html.hana-dark *,
body.hana-dark * {
  scrollbar-width: thin;
  scrollbar-color: rgba(61, 82, 74, 1) transparent;
}

/* ── SmartTheme 原生变量（ST 主题系统的核心，rgba 格式） ── */
html.hana-dark,
body.hana-dark {
  --SmartThemeBodyColor: rgba(30, 41, 36, 1) !important;
  --SmartThemeBlurTintColor: rgba(30, 41, 36, 1) !important;
  --SmartThemeChatTintColor: rgba(34, 48, 42, 1) !important;
  --SmartThemeUserMesBlurTintColor: rgba(37, 51, 45, 1) !important;
  --SmartThemeBotMesBlurTintColor: rgba(37, 51, 45, 1) !important;
  --SmartThemeEmColor: rgba(216, 230, 221, 1) !important;
  --SmartThemeUnderlineColor: rgba(159, 211, 180, 1) !important;
  --SmartThemeQuoteColor: rgba(168, 192, 178, 1) !important;
  --SmartThemeBorderColor: rgba(61, 82, 74, 1) !important;
  --SmartThemeShadowColor: rgba(0, 0, 0, 0.45) !important;
  --SmartThemeMainColor: rgba(216, 230, 221, 1) !important;
  --SmartThemeBubbleBlurTintColor: rgba(37, 51, 45, 1) !important;
}

/* ── 自定义薄荷变量（同样 rgba） ── */
html.hana-dark,
body.hana-dark {
  --text-main: rgba(216, 230, 221, 1) !important;
  --text-soft: rgba(168, 192, 178, 1) !important;
  --text-italic: rgba(184, 212, 196, 1) !important;
  --bg-chat: rgba(30, 41, 36, 1) !important;
  --bg-ui: rgba(34, 48, 42, 1) !important;
  --bg-main: rgba(30, 41, 36, 1) !important;
  --bg-alt: rgba(37, 51, 45, 1) !important;
  --bg-hover: rgba(42, 58, 50, 1) !important;
  --bg-active: rgba(47, 65, 56, 1) !important;
  --border-ui: rgba(61, 82, 74, 1) !important;
  --border-main: rgba(61, 82, 74, 1) !important;
  --accent-mint-1: rgba(159, 211, 180, 1) !important;
  --accent-mint-2: rgba(123, 185, 154, 1) !important;
  --accent-ink: rgba(165, 207, 169, 1) !important;
  --accent-peach: rgba(240, 180, 160, 1) !important;
  --accent-cream: rgba(42, 58, 50, 1) !important;
  --accent-peach: rgba(93, 174, 142, 1) !important;
  background: rgba(30, 41, 36, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
}

/* ── 消息气泡 ── */
body.hana-dark .mes {
  background: rgba(37, 51, 45, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
}
body.hana-dark .mes.user {
  background: rgba(42, 58, 50, 1) !important;
}
body.hana-dark .mes_text,
body.hana-dark .mes_text * {
  color: rgba(216, 230, 221, 1) !important;
}
body.hana-dark .mes_quote {
  border-left-color: rgba(159, 211, 180, 1) !important;
}
body.hana-dark .mes_block {
  background: rgba(37, 51, 45, 1) !important;
}

/* ── 输入区 & 面板 ── */
body.hana-dark #input-bar,
body.hana-dark #form_send,
body.hana-dark .send_textarea,
body.hana-dark textarea#send_textarea,
body.hana-dark #send_form {
  background: rgba(34, 48, 42, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}
body.hana-dark .drawer,
body.hana-dark .drawer-content,
body.hana-dark #top-settings-holder,
body.hana-dark #right-nav-panel,
body.hana-dark #left-nav-panel,
body.hana-dark .drawer-content .flex-container {
  background: rgba(34, 48, 42, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
}

/* ── 顶栏按钮 & 抽屉图标（暗色下提亮，配合手绘 SVG） ── */
body.hana-dark .drawer-icon {
  filter: brightness(1.4) !important;
}
body.hana-dark .drawer-icon:hover {
  filter: brightness(1.7) !important;
  background-color: rgba(159, 211, 180, 0.22) !important;
}

/* ── 输入框文字、占位符 ── */
body.hana-dark #send_textarea::placeholder,
body.hana-dark input::placeholder {
  color: rgba(138, 163, 148, 1) !important;
}
body.hana-dark input,
body.hana-dark select,
body.hana-dark textarea {
  background: rgba(30, 41, 36, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}

/* ── 链接与 hover ── */
body.hana-dark a {
  color: rgba(159, 211, 180, 1) !important;
}
body.hana-dark .list-group-item:hover,
body.hana-dark .menu_button:hover,
body.hana-dark .menu_item:hover {
  background: rgba(42, 58, 50, 1) !important;
}

/* ── 欢迎页 & 主内容区（用户反馈主界面仍亮，重点覆盖） ── */
body.hana-dark #chat,
body.hana-dark .container,
body.hana-dark .mes-container,
body.hana-dark .chat-area,
body.hana-dark .flex-container.flexGap5,
body.hana-dark .sheldony {
  background: rgba(30, 41, 36, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
}

/* ── 滚动条（暗色适配） ── */
body.hana-dark ::-webkit-scrollbar-track {
  background: transparent !important;
}
body.hana-dark ::-webkit-scrollbar-thumb {
  background: rgba(61, 82, 74, 1) !important;
  border: 2px solid rgba(30, 41, 36, 1) !important;
}
body.hana-dark ::-webkit-scrollbar-thumb:hover {
  background: rgba(93, 174, 142, 1) !important;
}

/* ── 弹窗与覆盖层 ── */
body.hana-dark .popup,
body.hana-dark .popup-content,
body.hana-dark .popup-container,
body.hana-dark .overflow-container,
body.hana-dark .bogus_folder_select {
  background: rgba(34, 48, 42, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}

/* ── 角色卡列表、设置项 ── */
body.hana-dark .character_name,
body.hana-dark .character_list .character,
body.hana-dark .settings_panel,
body.hana-dark .panel {
  background: rgba(37, 51, 45, 1) !important;
  color: rgba(216, 230, 221, 1) !important;
  border-color: rgba(61, 82, 74, 1) !important;
}


/* ── 修复 small 小字：ST 源码 small { color: var(--SmartThemeBodyColor) }，
   暗色下 SmartThemeBodyColor=深绿黑 → 小字看不清。这里单独提亮 ── */
body.hana-dark small,
body.hana-dark small *,
body.hana-dark .range-block-range-and-counter small,
body.hana-dark .checkbox_label small,
body.hana-dark .checkbox_label small * {
  color: rgba(216, 230, 221, 1) !important;
}
